import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const SLUGS = [
  "best-vps-for-wordpress",
  "vps-vs-dedicated-server-which-do-you-need",
  "vps-vs-dedicated-game-server-hosting",
  "vps-vs-cloud-hosting-whats-the-difference",
  "how-to-set-up-a-counter-strike-2-dedicated-server",
];

function words(s: string) {
  return (s.trim().match(/\S+/g) || []).length;
}
function headings(md: string) {
  const h2 = (md.match(/^##\s+/gm) || []).length;
  const h3 = (md.match(/^###\s+/gm) || []).length;
  return { h2, h3 };
}
function hasTable(md: string) {
  return /^\s*\|.*\|.*\n\s*\|[-\s|:]+\|/m.test(md);
}
function hasFaq(md: string) {
  return /faq|frequently asked|q:|q&a/i.test(md);
}
// count internal links in body to /blog/... and to marketing pages
function internalLinks(md: string) {
  const links = [...md.matchAll(/\]\((\/[^)]*)\)/g)].map((m) => m[1]);
  return links;
}

async function main() {
  // All published posts for corpus-level analysis
  const all = await db.blogPost.findMany({
    where: { published: true },
    select: { id: true, slug: true, title: true, category: true, tags: true, body: true, excerpt: true },
  });
  console.log(`\n===== CORPUS: ${all.length} published posts =====`);

  // For each target slug, full analysis
  for (const slug of SLUGS) {
    const p = await db.blogPost.findUnique({ where: { slug } });
    console.log("\n\n#################################################");
    console.log("SLUG:", slug);
    if (!p) { console.log("  !!! NOT FOUND / not a row"); continue; }
    console.log("  published:", p.published, "| category:", p.category, "| tags:", JSON.stringify(p.tags));
    console.log("  TITLE:", p.title);
    console.log("  seoTitle:", p.seoTitle ?? "(none)");
    console.log("  seoDescription:", p.seoDescription ?? "(none)");
    console.log("  excerpt:", p.excerpt);
    console.log("  WORD COUNT (body):", words(p.body));
    const h = headings(p.body);
    console.log("  headings: H2=", h.h2, " H3=", h.h3, "| table:", hasTable(p.body), "| faq-ish:", hasFaq(p.body));
    const il = internalLinks(p.body);
    console.log("  INTERNAL LINKS in body (count):", il.length);
    console.log("  internal link targets:", JSON.stringify(il));

    // How many OTHER published posts link TO this slug in their body?
    const inbound = all.filter((o) => o.slug !== slug && o.body.includes(`/blog/${slug}`));
    console.log("  INBOUND links from other posts:", inbound.length, inbound.map((o) => o.slug));
  }

  // ---- Cannibalization scan: how many posts target vps-vs / comparison / wordpress / cs2 queries ----
  console.log("\n\n===== CANNIBALIZATION SCAN =====");
  const scanTerms: Record<string, RegExp> = {
    "vps vs dedicated": /vps vs dedicated|dedicated (server|vs)/i,
    "vps vs cloud": /vps vs cloud|cloud (vs|hosting)/i,
    "vps vs shared": /vps vs shared|shared hosting/i,
    "wordpress vps": /wordpress/i,
    "counter-strike 2 / cs2": /counter-?strike|cs2|cs:?go/i,
  };
  for (const [label, re] of Object.entries(scanTerms)) {
    const hits = all.filter((o) => re.test(o.title) || re.test(o.slug));
    console.log(`\n  [${label}] title/slug matches: ${hits.length}`);
    for (const hh of hits) console.log(`     - ${hh.slug}  ::  "${hh.title}"`);
  }

  // ---- Overlap among the 3 vps-vs comparison posts (shared marketing angle) ----
  console.log("\n\n===== VPS-VS CLUSTER: title dump of all 'vs' posts =====");
  const vsPosts = all.filter((o) => /\bvs\b|versus|difference|which/i.test(o.title) || /-vs-/.test(o.slug));
  for (const v of vsPosts) console.log(`   - ${v.slug}  ::  "${v.title}"  [tags: ${v.tags.join(",")}]`);
}

main().finally(() => db.$disconnect());

import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

const COMPETE = [
  // pillar candidate + direct competitors of the 5 targets
  "vps-vs-shared-vs-dedicated-vs-cloud-hosting",
  "vps-vs-shared-hosting-which-do-you-need",
  "shared-hosting-vs-vps-for-a-growing-site",
  "shared-hosting-vs-vps-which-to-choose",
  "why-a-vps-beats-shared-hosting-for-a-growing-site",
  "managed-vs-unmanaged-vps-which-should-you-choose",
  // wordpress competitors
  "how-to-host-wordpress-on-a-vps",
  "one-click-wordpress-hosting",
  "how-to-install-wordpress-on-a-vps-lemp-stack",
  "how-to-speed-up-wordpress-on-a-vps-with-caching",
  // cs2 direct duplicate
  "how-to-set-up-a-cs2-server",
];

function words(s: string) { return (s.trim().match(/\S+/g) || []).length; }

async function main() {
  const all = await db.blogPost.findMany({
    where: { published: true },
    select: { id: true, slug: true, body: true },
  });
  const inboundCount = (slug: string) =>
    all.filter((o) => o.slug !== slug && o.body.includes(`/blog/${slug}`)).map((o) => o.slug);

  for (const slug of COMPETE) {
    const p = await db.blogPost.findUnique({ where: { slug } });
    if (!p) { console.log(`\n${slug}: NOT FOUND`); continue; }
    const inb = inboundCount(slug);
    console.log(`\n${slug}`);
    console.log(`   title: "${p.title}" | cat: ${p.category} | tags: ${p.tags.join(",")}`);
    console.log(`   words: ${words(p.body)} | published: ${p.published} | publishedAt: ${p.publishedAt?.toISOString().slice(0,10)}`);
    console.log(`   inbound links: ${inb.length} ${JSON.stringify(inb)}`);
  }
}
main().finally(() => db.$disconnect());

